// นำเข้า "ยี่ห้อกรอบแว่น" จากประวัติการขายเดิม (OPTODB) — เอาแค่ระดับยี่ห้อ ไม่ลงรายละเอียดรุ่น/สี/รหัส เพราะหน้างานจริงพนักงานจะกรอกรหัส+สีของชิ้นที่ขายเองตอนเปิดบิล (ไม่ได้ใช้ตัดสต็อก)
// ราคาตั้งต้น = ราคามัธยฐาน (median) จากประวัติการขายจริงของยี่ห้อนั้น ปรับแก้ได้เสมอก่อนขายจริง
function importFrameBrands() {
  const existing = new Set(live('products').filter(p => p.product_type === 'frame').map(p => p.product_name));
  const toAdd = FRAME_BRAND_CATALOG.filter(([name]) => !existing.has(name));
  toAdd.forEach(([product_name, retail_price_thb]) => {
    save('products', { id: uid(), product_type: 'frame', product_name, brand: product_name, retail_price_thb, cost_thb: null, stock_qty: null, sku: null, active: true, lens_spec: {}, deleted_at: null });
  });
  persist();
  return toAdd.length;
}
// นำเข้า "ยี่ห้อเลนส์" อื่นๆ ที่ร้านเคยขายมาก่อน (นอกเหนือจาก HOYA/Apollo ที่มีแคตตาล็อกทางการอยู่แล้ว) แบบเดียวกับกรอบแว่น คือเอาแค่ระดับยี่ห้อ
function importLensOtherBrands() {
  const existing = new Set(live('products').filter(p => p.product_type === 'lens').map(p => p.product_name));
  const toAdd = LENS_OTHER_BRAND_CATALOG.filter(([name]) => !existing.has(name));
  toAdd.forEach(([product_name, retail_price_thb]) => {
    save('products', { id: uid(), product_type: 'lens', product_name, brand: product_name, retail_price_thb, cost_thb: null, stock_qty: null, sku: null, active: true, lens_spec: {}, deleted_at: null });
  });
  persist();
  return toAdd.length;
}
// ล้างของเก่า: กรอบแว่นที่เคยนำเข้าแบบ "รายรุ่น/รายสี" (1,579 รายการ) จากรอบนำเข้าครั้งก่อน ซึ่งตอนนี้เปลี่ยนมาใช้แบบ "รายยี่ห้อ" แทนแล้ว — รายการเก่าพวกนี้สังเกตได้จาก lens_spec.purchased_at ที่ถูกตั้งไว้ตอนนำเข้าครั้งนั้นเท่านั้น (กรอบที่เพิ่มเองไม่มีค่านี้)
function cleanupOldFrameImport() {
  const old = live('products').filter(p => p.product_type === 'frame' && p.lens_spec && p.lens_spec.purchased_at);
  old.forEach(p => save('products', { ...p, deleted_at: now() }));
  persist();
  return old.length;
}

