const HOYA_DATA_VERSION = 'fy26-v4-highlights';
// ซิงก์แคตตาล็อก HOYA เข้าในรายการสินค้าให้เป็นปัจจุบันเสมอ (เทียบด้วย HOYA_DATA_VERSION) — ไม่ทับสต็อก/ต้นทุนที่ร้านกรอกไว้เอง จับคู่ชุดตัวเลือกเดิมด้วย Index+Coating+เปลี่ยนสี
// กันรายการซ้ำ: ถ้าเครื่อง/แท็บมากกว่า 1 ตัวซิงก์พร้อมกันก่อนจะเห็นข้อมูลของกันและกัน อาจเผลอสร้างสินค้าชื่อเดียวกันซ้ำ 2 แถวขึ้นไปได้
// ฟังก์ชันนี้ไล่เช็คทุกครั้งที่ซิงก์ ถ้าเจอชื่อซ้ำกันในกลุ่ม HOYA จะเก็บไว้แถวเดียว (แถวที่สร้างก่อน) แล้วลบแถวที่ซ้ำออก
function dedupeHoyaProducts(hoyaNames) {
  const groups = {};
  live('products').forEach(p => { if (hoyaNames.has(p.product_name)) (groups[p.product_name] = groups[p.product_name] || []).push(p); });
  let removed = 0;
  Object.values(groups).forEach(list => {
    if (list.length <= 1) return;
    list.sort((a, b) => String(a.id).localeCompare(String(b.id)));
    list.slice(1).forEach(p => { save('products', { ...p, deleted_at: now() }); removed++; });
  });
  if (removed) persist();
  return removed;
}
function syncHoyaCatalog(opts) {
  const force = opts && opts.force;
  const newNames = new Set(HOYA_LENSES.map(o => o.product_name));
  dedupeHoyaProducts(newNames);
  // เช็คจำนวนจริงด้วย ไม่ใช่เช็คแค่ธงเวอร์ชัน — กันปัญหาธงบอกว่า "เสร็จแล้ว" ทั้งที่ข้อมูลจริงในเครื่องไม่ครบ (เช่น ตอนพื้นที่เก็บข้อมูลเคยเต็มแล้วบันทึกไม่สำเร็จ)
  const curHave = live('products').filter(p => newNames.has(p.product_name)).length;
  if (!force && ls.get('hoyaSyncVer', '') === HOYA_DATA_VERSION && curHave === newNames.size) return null;
  const byName = {}; live('products').forEach(p => { byName[p.product_name] = p; });
  const vkey = v => [v.index || '', v.coating || '', v.color_change || 'none'].join('|');
  let added = 0, updated = 0, removed = 0;
  HOYA_LENSES.forEach(o => {
    const old = byName[o.product_name];
    const oldVariants = (old && old.lens_spec && Array.isArray(old.lens_spec.variants)) ? old.lens_spec.variants : [];
    const oldByKey = {}; oldVariants.forEach(v => { oldByKey[vkey(v)] = v; });
    const variants = o.lens_spec.variants.map(v => {
      const match = oldByKey[vkey(v)];
      return { ...v, id: match ? match.id : uid(), stock_qty: match && match.stock_qty != null ? match.stock_qty : (v.stock_qty ?? null), cost: match && match.cost != null ? match.cost : (v.cost ?? null) };
    });
    const prices = variants.map(v => v.price);
    // ไม่เก็บรูปภาพ (photos/photo_url) ลงฐานข้อมูล/เครื่อง — รูปแคตตาล็อกหนักมาก เก็บซ้ำทุกเครื่อง/ทุกครั้งที่ซิงก์ทำให้พื้นที่เก็บข้อมูลในเครื่องเต็มจนบันทึกอะไรไม่ได้เลย
    // (แอปจะดึงรูปสดจาก HOYA_LENSES ในโค้ดแทนตอนแสดงผล ผ่าน lensPhotos())
    const { photos, photo_url, ...specRest } = o.lens_spec;
    save('products', {
      id: old ? old.id : uid(), product_type: 'lens', product_name: o.product_name, brand: o.brand, description: o.description,
      retail_price_thb: Math.min(...prices), cost_thb: old ? (old.cost_thb ?? null) : null, stock_qty: old ? (old.stock_qty ?? null) : null,
      features: old ? (old.features || []) : [], active: old ? old.active !== false : true, sku: old ? (old.sku || null) : null,
      lens_spec: { ...specRest, variants }, deleted_at: null,
    });
    old ? updated++ : added++;
  });
  live('products').filter(p => p.product_name.startsWith('HOYA ') && !newNames.has(p.product_name)).forEach(p => { save('products', { ...p, deleted_at: now() }); removed++; });
  ls.set('hoyaSyncVer', HOYA_DATA_VERSION);
  persist();
  return { added, updated, removed };
}

